package funciface

// PROBLEM
//
// Rule is a one-method interface, and every rule needs its own named type
// with a method, even when the rule is one line. A rule that is a single
// comparison costs a type and a method before it can be used. And a caller who
// already has a plain function cannot pass it where a Rule is expected.
//
// TRY IT
//
// Count the lines it takes to add a rule that allows numbers divisible by 3
// using the interface. Then look at how few a plain function would need.
//
// Do not edit this file. Your work goes in after.go.

// Rule decides whether a number is allowed.
type Rule interface {
	Allow(n int) bool
}

// AtLeast allows numbers at or above Min.
type AtLeast struct{ Min int }

func (r AtLeast) Allow(n int) bool { return n >= r.Min }

// Even allows even numbers.
type Even struct{}

func (Even) Allow(n int) bool { return n%2 == 0 }

// Filter returns the numbers the rule allows, in order.
func Filter(nums []int, r Rule) []int {
	var out []int
	for _, n := range nums {
		if r.Allow(n) {
			out = append(out, n)
		}
	}
	return out
}
